import{_ as e,c as s,o as a,a3 as n}from"./chunks/framework.Dokpd4od.js";const u=JSON.parse('{"title":"Adjustments","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/inventories/adjustments/index.md","filePath":"master/supply-chain/inventories/adjustments/index.md","lastUpdated":1792041590000}'),o={name:"master/supply-chain/inventories/adjustments/index.md"};function r(d,t,i,h,l,c){return a(),s("div",null,t[0]||(t[0]=[n(`<h1 id="adjustments" tabindex="-1">Adjustments <a class="header-anchor" href="#adjustments" aria-label="Permalink to &quot;Adjustments&quot;">​</a></h1><p>Your system stock and your real shelves will sometimes disagree. Goods get damaged, miscounted, lost or found. An adjustment brings the numbers in Aureus back in line with what is physically there, and keeps a record of why.</p><blockquote><p><strong>In simple words:</strong> Adjustments fix the stock numbers so they match what is on the shelf.</p></blockquote><p>Open them from <code>Inventory → Operations → Adjustments</code>. The group has two pages.</p><table tabindex="0"><thead><tr><th>Page</th><th>Use it to</th><th>Result</th></tr></thead><tbody><tr><td><strong>Quantities</strong></td><td>Count stock and correct the difference</td><td>On hand quantity changes to the counted quantity</td></tr><tr><td><strong>Scraps</strong></td><td>Remove damaged or unusable goods</td><td>Goods move to the scrap location</td></tr></tbody></table><h2 id="which-tool-should-you-use" tabindex="-1">Which tool should you use? <a class="header-anchor" href="#which-tool-should-you-use" aria-label="Permalink to &quot;Which tool should you use?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Best tool</th></tr></thead><tbody><tr><td>You counted a shelf and the number is different</td><td><a href="./inventory-adjustments.html">Inventory adjustments</a></td></tr><tr><td>A box fell and the items are broken</td><td><a href="./scrap.html">Scrap</a></td></tr><tr><td>You want to count many products on a schedule</td><td><a href="./inventory-adjustments.html">Inventory adjustments</a></td></tr><tr><td>You want to type a new on hand number straight in the stock report</td><td>See <a href="./../reporting/stock-report.html">Stock report</a></td></tr></tbody></table><p>Use a scrap when you know goods are destroyed and want to say so. Use an adjustment when you only know the count is wrong.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The <strong>Add Quantity</strong> button and the stock report both work on the same stock records as the Quantities page. The difference is the workflow: a count is saved first, then you apply it when you are ready.</p></div><h2 id="the-flow" tabindex="-1">The flow <a class="header-anchor" href="#the-flow" aria-label="Permalink to &quot;The flow&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Count the shelf</span></span>
<span class="line"><span>      |</span></span>
<span class="line"><span>      v</span></span>
<span class="line"><span>Type the Counted Quantity on the row</span></span>
<span class="line"><span>      |</span></span>
<span class="line"><span>      v</span></span>
<span class="line"><span>Check the Difference column</span></span>
<span class="line"><span>      |</span></span>
<span class="line"><span>      v</span></span>
<span class="line"><span>Apply   (stock is corrected)     or     Clear   (count is discarded)</span></span></code></pre></div><p>For damaged goods the flow is shorter: create a scrap, then click <strong>Validate</strong>.</p><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><p>Every correction is stored as a stock move, so you can trace it later in <a href="./../reporting/moves-history.html">Moves history</a>. Adjustments use the virtual location <code>Virtual Locations/Inventory Adjustment</code>. Scraps use <code>Virtual Locations/Scrap</code>. Neither location counts as sellable stock.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./inventory-adjustments.html">Inventory adjustments</a></li><li><a href="./scrap.html">Scrap</a></li><li><a href="./../reporting/stock-report.html">Stock report</a></li><li><a href="./../warehouses/locations.html">Locations</a></li></ul>`,16)]))}const m=e(o,[["render",r]]);export{u as __pageData,m as default};
